    description: 'Stundenglass® is the Gravity Infuser you have been dreaming about , a smart and elegantly designed 360° rotating glass infuser that catalyses active motion via cascading water displacement, opposing airflow technology and the natural force of gravity. This fluid physics generates a smooth hydrated smoke coming from the hose tip. How to use the Stundenglass Gravity Infuser? Assemble your Studenglass buttom glass and put the base on a leveled surface. Screw on the mouthpiece and ensure it&#8217;s secure. Twist on the percolator in a clockwise rotation. Fill the bottom glass bowl with three cups of water or up to the lip of the bottom globe. Thread the top glass bowl and make one full rotation to ensure all seals are secure. Start by threading the adapter into the culture. Next , place the adapter into the female intake elbow with the rubber grommet and place the bowl onto the grommet. Pack the bowl with your favourite material. Prep your coals we found self-igniting coal works the best as they are clean and easy to use. Rotate the unit multiple times. Let it cool before handling lift the whole assembly from the colt ring, if you like to use the hose attachment, attach the glass mouthpiece to hookah wand and then to the 3 Ft hose. Affixed the male to male adapter onto the mouthpiece connect the hose to the adapter. Fill with smoke and simply pull from the mouthpiece or rotate the unit again to force the smoke out for a more contactless experience. Vapor Quality Vapor quality of the Stundenglass gravity hookah is a top rated experience! The long length of the vapor hose and water filtering makes the vapor cold. This making it ideal to enjoy high-quality water-filtered vapor from your favourite material at home. The visible water filtering is indeed a elevated smoking experience. Stundenglass Gravity Infuser Temperature Settings The Stundenglass Gravity Rotating Bong is heated by coal, there are no temperature settings on the device. The G Pen Connect or the Stündenglass Modül are amazing additions to the Studenglass gravity bong as they fit perfect. Build Quality Assembled using the highest quality materials, including borosilicate glass globes and aircraft-grade anodized aluminium, the Stundenglass Gravity Infuser evokes an immersive experience while delivering smooth, consistent and tasty draws. Made for functional versatility, the Stündenglass Gravity Infuser comes with a complete set that includes an aluminium bowl kit and a glass liner, but can also connect to any smoking or vaporization device with a 14mm male joint. Included is a 3-foot silicone hose that can be connected for direct draws, though a steady stream of smoke through the 45° adjustable mouthpiece affords the optionality for entirely contactless consumption. Gravity Infuser comes packaged in a reusable craft box with a handle, allowing for safe storage and transportation. Removable Borosilicate Glass Globes The globes included with the Stundenglass Gravity Infuser are made from a durable material that can withstand use over time. Additionally, these globes are dishwasher-safe, making cleaning and maintenance a breeze. Assembling the globes is also a simple process, ensuring that you can enjoy your Stundenglass Gravity Infuser with ease. Stundenglass Collaborations Stündenglass comes in more than just black; it boasts exciting collaborations with some of the industry&#8217;s top brands like Grateful Dead, Cookies, Dr. Greenthumb&#8217;s, and Mike Tyson 2.0. What can you vape with the Stundenglass Gravity Bong? This is the best part, with the Studenglass Gravity Bong you can vape and smoke a lot of materials, such as: Dry Herbs Concentrate or wax Tobacco Liquids ( used by professional mixologists ) Beverages Food Can you dab with a Stündenglass? Yes, you can absolutely dab with a Stündenglass Gravity Infuser. The versatility of this device allows it to be used for both vaping and dabbing purposes. Dabbing is a popular method of consuming cannabis concentrates, such as wax or shatter, and the Stündenglass Gravity Infuser provides an exceptional experience for dab enthusiasts. To dab with the Stündenglass Gravity Infuser, you will need a dab rig attachment. This attachment connects to the 14mm male joint of the device, providing a seamless and secure connection for your dabbing needs. Once the attachment is in place, you can heat up your dab nail or banger and apply your preferred concentrate onto it. When it comes to dabbing with the Stündenglass Gravity Infuser, you have the option of using a traditional torch to heat up your nail or opting for an electric dab rig attachment. Whichever method you choose, the Stündenglass Gravity Infuser is designed to deliver smooth and flavorful dabs, allowing you to enjoy the full potential of your concentrates. Who invented the flip Gravity Bong? Seth Rogen&#8217;s Gravity Bong is a New Lesson in Bong-ineering. A celebrity endorsement can go a long way toward ensuring success of this product. We at Herbalize Store are proud authorized retailers. Is the Stundenglass gravity bong worth it? So is the Stundenglass Gravity Infuser cheap or to expensive? This device has a premium feeling to all aspects. Super durable, futuristic in design and superb in function, the Stündenglass Gravity Infuser stands alone at the pinnacle of smoking and vaporization devices. What&#8217;s in the box? 1x Stundenglass Gravity Infuser device 2x Borosilicate Glass Globes 1x Glass Liner 1x Cleaning Kit 1x 14mm Male-to-Male Adapter 1x Travel Case 1x Coal Tray 1x Glass Bowl Insert 1x 3 Ft Hose',
