    description: 'Description Phoenix Star Gravity Bong PHX876 is a simple yet effective glass water pipe that utilizes gravity to filter and inhale smoke. It can deliver a highly concentrated dose of smoke in a short amount of time, leading to a more intense effect. The gravity bong features two high-quality borosilicate glass bodies. The inner bottle has a perforated bottom with a silicone grommet that protects where the glass connects with the base. The top comes with a 14mm bowl, which, though it only holds a small amount of tobacco, is more than sufficient. The smoke is contained within the bottle, ensuring no waste at all. This glass bong is perfect for smoking enthusiasts who prefer a strong and potent hit. How to use a glass gravity bong: &#8211; Fill the base about halfway with water. &#8211; Pack the bowl with dry herbs and insert it into the joint at the top. &#8211; Light the bowl and lift the inner bottle at the same time. Don&#8217;t lift the bottle out of the water, or you&#8217;ll lose your smoke. &#8211; Once the bottle is full of smoke, remove the bowl and place your mouth over the top, inhaling as you lower the bottle. The Gravity bong will give you a dense, pressurized hit with no loss of smoke in the process',
